output_text:
[
  {
    "id": "no_cart_single_file",
    "text": "Shopping carts are not allowed in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "park_before_entering_single_file",
    "text": "Before entering a single-file aisle, the shopper must leave the cart at the aisle mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "enterSingleFile": {
          "pre": {
            "and": [
              "singleFileMouth",
              "N"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "enterSingleFile",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "single_file_shelf_service_cart_free",
    "text": "Shelf interactions inside single-file aisles must be done without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfPosition": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfPosition",
          "INTERACT",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "reclaim_parked_cart",
    "text": "Anyone who parks a cart must later reclaim it before finishing the trip.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "reclaimCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "reclaimCart"
    }
  },
  {
    "id": "do_not_walk_away_from_parked_cart",
    "text": "After returning to a cart-parking mouth without the cart, the shopper must pick it up rather than walk away.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartParkingMouth",
          {
            "not": "hasCart"
          },
          "MOVE"
        ]
      }
    }
  },
  {
    "id": "cart_required_outside_exempt_zones",
    "text": "Except at the entrance, cart bay, single-file aisles, and their mouths, shoppers should remain with their cart.",
    "abstraction": {
      "state_properties": {
        "entranceOrCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartExemptZone": {
          "or": [
            "entranceOrCartBay",
            "singleFileAisle",
            "singleFileMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "cartExemptZone"
          }
        ]
      }
    }
  },
  {
    "id": "park_only_in_wide_cross_aisles",
    "text": "Carts may only be parked in wide cross-aisles, not in narrow or shelf-constrained passages.",
    "abstraction": {
      "state_properties": {
        "wideCrossAisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "wideCrossAisle"
          }
        ]
      }
    }
  },
  {
    "id": "return_from_single_file_before_exit",
    "text": "After shopping in a single-file aisle, the shopper must return to an aisle mouth before exiting.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShoppingPoint": {
          "and": [
            "singleFileAisle",
            "adjShelf"
          ]
        },
        "singleFileMouthWithoutCart": {
          "and": [
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            },
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "singleFileShoppingPoint",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      },
      "discharge": "singleFileMouthWithoutCart"
    }
  }
]
